// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GpuUsageSync) predicate.GpuUsageSync {
	return predicate.GpuUsageSync(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GpuUsageSync) predicate.GpuUsageSync {
	return predicate.GpuUsageSync(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GpuUsageSync) predicate.GpuUsageSync {
	return predicate.GpuUsageSync(sql.NotPredicates(p))
}
